import{c as a,Q as d,j as r,m as e}from"./chunks/framework.btqkto0n.js";const u=JSON.parse('{"title":"搜索录入","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sourcing-playbook.md","filePath":"guide/sourcing-playbook.md"}'),o={name:"guide/sourcing-playbook.md"};function i(l,t,h,n,s,b){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="搜索录入" tabindex="-1">搜索录入 <a class="header-anchor" href="#搜索录入" aria-label="Permalink to &quot;搜索录入&quot;">​</a></h1><h2 id="搜索渠道" tabindex="-1">搜索渠道 <a class="header-anchor" href="#搜索渠道" aria-label="Permalink to &quot;搜索渠道&quot;">​</a></h2><h3 id="权威精准" tabindex="-1">权威精准 <a class="header-anchor" href="#权威精准" aria-label="Permalink to &quot;权威精准&quot;">​</a></h3><p>优先用官方文档、技术博客、开源项目文档、机构课程、白皮书和行业报告。适合核对定义、版本、参数、限制和主流产品信息。</p><p>常用搜索式：</p><table tabindex="0"><thead><tr><th>目的</th><th>搜索公式</th></tr></thead><tbody><tr><td>官方定义</td><td>产品名词 + 官方文档</td></tr><tr><td>概念说明</td><td>名词 + 介绍</td></tr><tr><td>行业趋势</td><td>人工智能行业白皮书</td></tr><tr><td>生成式 AI 趋势</td><td>生成式 AI 发展报告</td></tr></tbody></table><h3 id="小白科普" tabindex="-1">小白科普 <a class="header-anchor" href="#小白科普" aria-label="Permalink to &quot;小白科普&quot;">​</a></h3><p>用于改写成人话，不能直接当权威来源。可参考知乎、掘金、稀土、InfoQ、少数派、爱范儿、B 站、百度百科、维基百科、菜鸟教程。</p><h3 id="查漏补缺" tabindex="-1">查漏补缺 <a class="header-anchor" href="#查漏补缺" aria-label="Permalink to &quot;查漏补缺&quot;">​</a></h3><p>专项搜索命令行、框架、数据库和 AIGC 细分主题。</p><table tabindex="0"><thead><tr><th>类目</th><th>搜索公式</th></tr></thead><tbody><tr><td>命令行</td><td>ffmpeg 常用命令 教程</td></tr><tr><td>代码管理</td><td>git 入门指令</td></tr><tr><td>依赖</td><td>npm 依赖大全</td></tr><tr><td>前端</td><td>Vue 基础概念</td></tr><tr><td>数据库</td><td>Redis 作用 通俗讲解</td></tr><tr><td>AIGC</td><td>提示词工程 基础</td></tr><tr><td>AI 风险</td><td>AI 幻觉 是什么</td></tr></tbody></table><h2 id="关键词公式" tabindex="-1">关键词公式 <a class="header-anchor" href="#关键词公式" aria-label="Permalink to &quot;关键词公式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>公式</th><th>用途</th></tr></thead><tbody><tr><td>名词 + 通俗解释</td><td>拿大白话文案</td></tr><tr><td>名词 + 是什么 + 作用</td><td>得到定义和用途</td></tr><tr><td>名词 + 入门教程</td><td>补实操和案例</td></tr><tr><td>名词1 + 名词2 + 区别</td><td>做对比类卡片</td></tr><tr><td>AI + 类目 + 知识点汇总</td><td>批量收集整类内容</td></tr></tbody></table><h2 id="录入规则" tabindex="-1">录入规则 <a class="header-anchor" href="#录入规则" aria-label="Permalink to &quot;录入规则&quot;">​</a></h2><ol><li>同一个名词至少看 1 个官方来源，再用 2 篇正规科普辅助理解。</li><li>删除营销话术和夸张结论，只保留定义、作用、用法和边界。</li><li>命令、工具、依赖类内容能测试就先测试，再写入卡片。</li><li>单张卡片只讲一个主概念，重复概念做引用，不新建重复卡。</li><li>卡片按固定结构写：标题、配图、一句话解释、核心作用、简单例子、官方来源、注意事项。</li></ol><h2 id="扩充节奏" tabindex="-1">扩充节奏 <a class="header-anchor" href="#扩充节奏" aria-label="Permalink to &quot;扩充节奏&quot;">​</a></h2><p>先填满一级大类，再细化二级知识点，最后补行业应用和前沿新名词。模型、工具出新版本时，新增卡片或标注新版变化；淘汰内容标注已下线或旧版。</p>',17)])])}const p=a(o,[["render",i]]);export{u as __pageData,p as default};
